import{_ as t}from"./chunks/results-publish-menu.DbSoSS9f.js";import{c as s,Q as o,j as r,m as n}from"./chunks/framework.BqPkuuVc.js";const a="/assets/results.QIOkOxC4.png",i="/assets/results-organisations-chosen.CI75ajy8.png",l="/assets/results-publish-options-organisations.V6anvjbf.png",h="/assets/results-publish-options-html.BegH9aB2.png",d="/assets/results-html-page.BZZhOWr6.png",u="/assets/event-not-finalised-publish.YK4OA5-N.png",c="/assets/results-print-relay.DyCpYd4x.png",T=JSON.parse('{"title":"Results","description":"","frontmatter":{},"headers":[],"relativePath":"user/after-the-event/results.md","filePath":"user/after-the-event/results.md"}'),g={name:"user/after-the-event/results.md"};function p(m,e,f,w,y,b){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators checking, sharing and publishing results, during the event and after it.</p><p>How to read the <strong>Results</strong> screen, get results to spectators while the event runs, settle and publish the final results, and produce prize-giving lists.</p><h2 id="the-results-screen" tabindex="-1">The Results screen <a class="header-anchor" href="#the-results-screen" aria-label="Permalink to &quot;The Results screen&quot;">​</a></h2><p>Open the event and choose <strong>Results</strong> under <strong>Race</strong> in the event menu. It lists each class with its competitors in place order, and updates by itself as cards are downloaded and radio punches arrive, so you can leave it open.</p><p><img src="'+a+'" alt="The Results screen: results by class, with Place, Name, Club and Time for each competitor, and the Filters, Display and Include options on the right"></p><p>Each class shows:</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Place</strong></td><td>The finishing place. Only competitors with an <strong>OK</strong> result have one.</td></tr><tr><td><strong>Name</strong>, <strong>Club</strong></td><td>The competitor and their club. <strong>Club</strong> is left out when you are looking at one club&#39;s results.</td></tr><tr><td><strong>Behind</strong></td><td>How far behind the winner, when <strong>Show behind time</strong> is ticked. On a score course it&#39;s how many points behind.</td></tr><tr><td><strong>Points</strong>, <strong>Penalty</strong></td><td>On a score course only: the points collected, and what the time limit took off, if anyone lost any.</td></tr><tr><td><strong>Leg time</strong></td><td>In a relay class: each runner&#39;s own time on their leg (see <a href="#relays">Relays</a>).</td></tr><tr><td><strong>Time</strong></td><td>The race time, including any adjustment you made. For anyone without an OK result it shows their status instead: <strong>MP</strong>, <strong>DNF</strong>, <strong>DSQ</strong> and so on.</td></tr></tbody></table><p>Finishers come first, in place order; competitors with any other result follow them, greyed out. How ties and the order of non-finishers are decided is in <a href="./../reference/status-and-race-time#how-results-are-ordered">How results are ordered</a>.</p><p>The Results screen shows no splits. To see them:</p><ul><li><strong>One runner&#39;s</strong> — click their card number on the <strong>Card downloads</strong> page to open the <a href="./../running-the-event/card-download#the-card-download-detail-dialog">card download detail dialog</a>, with every control, code and split.</li><li><strong>Everyone&#39;s, control by control</strong> — the spectator site&#39;s <a href="./../screens/spectator-site-and-kiosk#splits">Splits</a> page, a table for each class or course.</li><li><strong>Radio splits on a TV</strong> — a <a href="./../screens/leaderboard#radio-control-columns">Leaderboard</a> screen has a column for each radio control.</li></ul><p>Below the classes, <strong>Summary</strong> gives a line per class: how many entries, the winning time, and how many have each status. Its <strong>On course</strong> column is the quickest way to see which classes are still incomplete.</p><h3 id="choosing-what-s-shown" tabindex="-1">Choosing what&#39;s shown <a class="header-anchor" href="#choosing-what-s-shown" aria-label="Permalink to &quot;Choosing what&#39;s shown&quot;">​</a></h3><p>The panel on the right changes what&#39;s on the screen, and what <strong>Print view</strong> and <strong>Export PDF</strong> produce from it. It is reset when you leave the screen.</p><p><strong>Filters</strong></p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Group by</strong></td><td><strong>Class</strong> (the default) or <strong>Course</strong>. By course puts everyone who ran the same course into one list, whatever their class.</td></tr><tr><td><strong>Classes</strong> / <strong>Courses</strong></td><td>Only these classes or courses. Leave it empty for all of them.</td></tr><tr><td><strong>Organisation</strong></td><td>Only competitors from these clubs: results for one club&#39;s newsletter, say. The heading becomes &quot;Results for <em>club</em>&quot;.</td></tr><tr><td><strong>Show</strong></td><td><strong>All</strong>, or only the <strong>Top 3</strong> to <strong>Top 10</strong> of each class.</td></tr></tbody></table><p><img src="'+i+'" alt="The Results screen with Organisation set to two clubs, Bayside Kangaroos and Bushflyers: the heading reads &quot;Results for Bayside Kangaroos, Bushflyers&quot;, each class lists only their runners with their places in the whole class (1, 3 and 6 in M21E), and the summary is headed with the two clubs too."></p><p><strong>Display</strong></p><ul><li><strong>Show behind time</strong> — adds the <strong>Behind</strong> column. Off to begin with.</li><li><strong>Show summary</strong> — the summary table at the bottom. On to begin with.</li></ul><p><strong>Include</strong></p><p>These add competitors who are normally left out of the lists. All four are off to begin with:</p><ul><li><strong>Provisional results</strong> — competitors who crossed a radio finish but whose card hasn&#39;t been downloaded. They have a time and a place, marked with <code>*</code>, and may still change: the card might show a missed control. See <a href="./../reference/status-and-race-time#provisional-vs-final-ok">Provisional vs final OK</a>.</li><li><strong>On course competitors</strong> — those still out, for a picture of the class with the field not yet home.</li><li><strong>Status none competitors</strong> — those nobody has accounted for yet.</li><li><strong>Did not start</strong> — those marked <strong>DNS</strong>.</li></ul><blockquote><p><strong>Note:</strong> <strong>Include</strong> only changes what you see here. An exported results file, or an upload to Eventor, always accounts for everyone in the classes you choose, whatever is ticked. See <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</p></blockquote><h3 id="relays" tabindex="-1">Relays <a class="header-anchor" href="#relays" aria-label="Permalink to &quot;Relays&quot;">​</a></h3><p>A relay class lists each <strong>team</strong> with its place and total time, and the team&#39;s runners underneath in leg order. For each runner, <strong>Leg time</strong> is their own time on their leg, with a status beside it if their leg went wrong, and <strong>Time</strong> is the team&#39;s running total at their changeover. On the last leg, that is the team&#39;s result. See <a href="./../event-setup/relay-events">Relay events</a>.</p><h2 id="results-while-the-event-is-running" tabindex="-1">Results while the event is running <a class="header-anchor" href="#results-while-the-event-is-running" aria-label="Permalink to &quot;Results while the event is running&quot;">​</a></h2><p>The Results screen is for you. Spectators, competitors and the people at home see results elsewhere, and each of these updates on its own as the race goes on:</p><table tabindex="0"><thead><tr><th>Where</th><th>Who sees it</th><th>Set up on</th></tr></thead><tbody><tr><td><strong>TV screens</strong> at the arena</td><td>Everyone at the event</td><td><a href="./../screens/tv-screens">TV screens</a></td></tr><tr><td>The <strong>spectator site</strong> and the <strong>kiosk</strong>, on phones and a tablet at the arena</td><td>Anyone on the event&#39;s network</td><td><a href="./../screens/spectator-site-and-kiosk">Spectator site and kiosk</a></td></tr><tr><td><strong>Commentary</strong></td><td>The commentator</td><td><a href="./../screens/commentary">Commentary</a></td></tr><tr><td><strong>liveresultat.orientering.se</strong></td><td>Anyone on the internet</td><td><strong>Event details → Live results</strong> (see <a href="./../running-the-event/publishing-live-results">Publishing live results online</a>)</td></tr><tr><td>The <strong>meshO cloud</strong></td><td>Anyone on the internet, once the event is published there</td><td><strong>Settings → <a href="./../reference/settings#cloud-sync">Cloud sync</a></strong>, and <strong>Event details → Cloud sync</strong> for each event (see <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing live results online</a>)</td></tr><tr><td>A <strong>live export</strong> file, rewritten every few minutes, for another results system to read</td><td>That system</td><td><strong>Event details → Backup &amp; export → Live export</strong> (see <a href="./../event-setup/create-event#live-export">Creating an event</a>)</td></tr></tbody></table><p>Each of these shows the race as it happens. Runners still on course appear as on course, and a radio finish appears with its time before the card is read. That&#39;s the point of a live feed, and it is different from the final results file below.</p><p>Two things hold results back on purpose:</p><ul><li><strong>Results quarantine.</strong> An elite class can have its results held back from every public screen until a set time or the last start, while its start list stays visible. You still see everything here. See <a href="./../event-setup/results-quarantine">Results quarantine</a>.</li><li><strong>liveresultat only publishes while the event is live.</strong> Nothing is sent before <strong>Start event</strong>, or after the event is finished.</li></ul><h2 id="publishing-the-final-results" tabindex="-1">Publishing the final results <a class="header-anchor" href="#publishing-the-final-results" aria-label="Permalink to &quot;Publishing the final results&quot;">​</a></h2><p>When the last runner is home and every result is settled, publish from <strong>Publish</strong> at the top of the Results screen:</p><p><img src="'+t+'" alt="The Publish menu open on the Results screen: Export IOF XML, Export JSON, Export PDF, Export HTML, Print view and Print to splits printer"></p><table tabindex="0"><thead><tr><th>Item</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Export IOF XML…</strong></td><td>The standard results file for other systems, and for uploading to Eventor by hand.</td></tr><tr><td><strong>Export JSON…</strong></td><td>The same results in <a href="./../advanced/orienteering-json">Orienteering JSON</a>.</td></tr><tr><td><strong>Export PDF…</strong></td><td>A results document to share or archive.</td></tr><tr><td><strong>Export HTML…</strong></td><td>A results web page to put on your club&#39;s website (see <a href="#a-results-page-for-your-website">A results page for your website</a>).</td></tr><tr><td><strong>Upload to Eventor…</strong></td><td>Sends the results straight to the event on Eventor. Only offered when Eventor is set up in <strong>Settings → <a href="./../reference/settings#eventor">Eventor</a></strong>.</td></tr><tr><td><strong>Print view…</strong></td><td>Opens the browser&#39;s print dialog with a printable page of the results.</td></tr><tr><td><strong>Print to splits printer…</strong></td><td>Prints a results sheet on a thermal printer (see <a href="#prize-giving-and-the-results-board">Prize-giving and the results board</a>).</td></tr></tbody></table><p>Each opens <strong>Publish options</strong> first. For the PDF, the web page and the print view you choose the classes, the grouping, the clubs, top places only or everyone, and whether to show the behind time and the summary. For a file or an upload you choose the classes and whether competitors marked <strong>DNS</strong> go in (<strong>Include DNS competitors</strong>). If anyone in the file was timed from a check punch or from midnight rather than a recorded start, the dialog says how many: their times and places go out as they are, so check them first if that matters. The options for a file, such as one country&#39;s results or combined classes for the World Ranking, are covered in <a href="./exports">Exporting data</a>.</p><p><img src="'+l+'" alt="Publish options for a PDF: Include DNS competitors, Classes (All classes), Group by Class, and Organisation open with Bayside Kangaroos and Bushflyers ticked."></p><h3 id="a-results-page-for-your-website" tabindex="-1">A results page for your website <a class="header-anchor" href="#a-results-page-for-your-website" aria-label="Permalink to &quot;A results page for your website&quot;">​</a></h3><p><strong>Publish → Export HTML…</strong> downloads the results as a single web page (an <code>.html</code> file) that you can upload to your club&#39;s website, or open in any browser. It&#39;s laid out like the PDF: a table for each class or course, with a list of them at the top linking to each one.</p><p>In <strong>Publish options</strong> you get the same choices as for the PDF, and two of its own:</p><ul><li><strong>Include splits</strong> adds a column for each control to the class&#39;s table, the way the spectator site&#39;s <a href="./../screens/spectator-site-and-kiosk#splits">Splits</a> page shows them in its <strong>Ranks</strong> view (details below).</li><li><strong>Your own style sheet</strong> is for when you want the page to match your website (below). Leave it empty to use meshO&#39;s styles.</li></ul><p><img src="'+h+'" alt="Publish options for a web page: Include DNS competitors, Classes, Group by Class, Organisation, Show All, Show behind time and Show summary ticked, then Include splits ticked and Your own style sheet holding a club website&#39;s address"></p><p>Click <strong>Export HTML</strong> and the page downloads, named like the PDF (for example <em>City Sprint Championships results.html</em>). With meshO&#39;s styles it looks like this, and it switches to dark colours on a phone or computer set to dark mode:</p><p><img src="'+d+'" alt="The exported results page open in a browser: the heading Results by class, a list of classes linking to each table, and a class table with place, name, club and time, then a column for each control holding each runner&#39;s time and rank there, the leaders and fastest legs coloured"></p><h4 id="the-splits-columns" tabindex="-1">The splits columns <a class="header-anchor" href="#the-splits-columns" aria-label="Permalink to &quot;The splits columns&quot;">​</a></h4><p>Each control&#39;s column is headed with its number on the course over its code, and the last is the finish. In each runner&#39;s cell:</p><ul><li>The top time is the time since the start, and the bottom one the time for the leg. Each has the runner&#39;s rank in brackets, for example <code>4:10 (2)</code>.</li><li>A <strong>green</strong> top time means the runner was <strong>leading</strong> at that control.</li><li>A <strong>blue</strong> leg time is the <strong>fastest</strong> leg into that control. The second and third fastest are in <strong>bold</strong>.</li><li>A leg with a <strong>red outline</strong> was a <strong>costly mistake</strong>: it took the runner about a third longer than it should have, judged against their own pace over the rest of the course. This is the same mistake marking the spectator site&#39;s Splits page uses.</li><li>The first three places are marked gold, silver and bronze.</li></ul><p>The ranks count everybody who ran that course, even when the page shows only some of them (for example <strong>Show Top 3</strong>, or one organisation). A runner who mispunched or didn&#39;t finish is shown for reference: their times are there, without ranks, and a control they missed has a dash. A control the course let them leave out says <strong>skipped</strong>.</p><p>A class that ran several courses (or a forked course) gets a table for each, headed with the course&#39;s name. Runners whose card wasn&#39;t read have no splits, and are listed after, under <strong>No splits</strong>. On a score or scatter course the columns are the controls in the order each runner visited them, with each control&#39;s code in the cell and no ranks. Relay teams don&#39;t get splits.</p><p>On a narrow screen the table scrolls sideways, with the place and name staying put.</p><p>If the splits or the mistake marking can&#39;t be loaded, Manager says <strong>Failed to export HTML.</strong> and downloads nothing, rather than a page with them missing. Try again once the connection to Manager is back.</p><h4 id="using-your-own-styles" tabindex="-1">Using your own styles <a class="header-anchor" href="#using-your-own-styles" aria-label="Permalink to &quot;Using your own styles&quot;">​</a></h4><p>meshO&#39;s styles are built into the top of the page, in one block. Nothing else in the page sets how it looks, so you can change all of it.</p><p>To make the page match your website:</p><ol><li>Export the page once with <strong>Your own style sheet</strong> empty.</li><li>Open it in a text editor and copy everything between <code>&lt;style id=&quot;mesho-results-style&quot;&gt;</code> and <code>&lt;/style&gt;</code> into a new file, for example <code>results.css</code>. Its first lines list every part of the page you can style.</li><li>Change the file to suit your site, and upload it to your website. The colours and font are set once at the top of the file, so changing those is a quick start.</li><li>Next time, put the file&#39;s address in <strong>Your own style sheet</strong>, for example <code>https://yourclub.org/results.css</code>, or just <code>results.css</code> if the page will sit in the same folder. The page then links your file and carries none of meshO&#39;s styles.</li></ol><p>Manager remembers the address on this computer, so you only type it once. To go back to meshO&#39;s styles, clear the field.</p><p>The whole page sits inside one <code>&lt;div class=&quot;mesho-results&quot;&gt;</code>, and meshO&#39;s styles only apply inside it. So you can also paste that part of the page into a page on your website and keep your site&#39;s own header and menus around it.</p><h3 id="settling-everyone-first" tabindex="-1">Settling everyone first <a class="header-anchor" href="#settling-everyone-first" aria-label="Permalink to &quot;Settling everyone first&quot;">​</a></h3><p>A results file says what became of <strong>everyone</strong> who took part, so Manager checks first. If anybody in the classes you chose still has no status, is still on course, or has only a radio finish, you see <strong>Event not finalised</strong> instead of the options:</p><p><img src="'+u+'" alt="Event not finalised: counts of competitors with no status, on course, with a radio finish only, and a radio finish nobody is entered on, with buttons to settle each"></p><p>Its buttons settle each group: <strong>Set competitors DNS…</strong> for those who never started, <strong>Set competitors overtime or DNF…</strong> for those still out, and <strong>Set radio finishes DNF or overtime…</strong> for finishes whose card was never read. <strong>Show pending…</strong> covers a card that finished but belongs to nobody, and <strong>Show on course…</strong> covers one that&#39;s still out. Once everyone is settled, Manager carries on to the publish options.</p><p><strong>Ignore and continue</strong> publishes anyway. Those with no status go in as <strong>DNS</strong>, and those still out or with only a radio finish as <strong>DNF</strong>. Settling them properly is better: a DNF in a published results file is a statement about a runner. The full rules, and how this works at a multi-day event, are in <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</p><p><strong>Finish event</strong> runs the same check. There the button reads <strong>Finish anyway</strong>, and it isn&#39;t offered while a radio finish is still waiting for its card (or a card that finished belongs to nobody): download the card, or settle it with the buttons, first. So the usual order at the end of the day is:</p><ol><li>Download the last cards and settle anyone left over (the dashboard&#39;s <strong>On course</strong> and <strong>Pending</strong> counts show who).</li><li>Click <strong>Finish event</strong>.</li><li>Publish: upload to Eventor, export the file your federation wants, print or export the PDF, and export the web page for your website.</li></ol><p>There is no separate &quot;mark as official&quot; step. A result is final once the card is read, and the file is complete once everyone is settled. If cloud sync is on, finishing the event also publishes it to the cloud (see <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing to the meshO cloud</a>).</p><h3 id="when-a-result-is-disputed" tabindex="-1">When a result is disputed <a class="header-anchor" href="#when-a-result-is-disputed" aria-label="Permalink to &quot;When a result is disputed&quot;">​</a></h3><p>A protest or a mistake found later is fixed on the competitor, not on the Results screen. Open the competitor (<strong><a href="./../event-setup/competitors-clubs-teams#adding-or-editing-a-competitor">Edit competitor</a></strong>):</p><ul><li><strong>To disqualify, or to record DNF or Overtime</strong>, change the <strong>Status</strong> on the <strong>Result</strong> tab.</li><li><strong>To give a control a runner did visit</strong>, override the punch on the <strong>Overrides</strong> tab. You can&#39;t set <strong>OK</strong> directly while the card shows a missed control: Manager checks OK against the punches, so a corrected punch is what turns an <strong>MP</strong> into an <strong>OK</strong>.</li><li><strong>To correct a start or finish time</strong>, use the <strong>Overrides</strong> tab as well.</li></ul><p>The Results screen, the public screens and the live feeds update straight away. A file you have already exported or uploaded does not: export or upload it again. The competitor&#39;s <strong>Audit trail</strong> tab records what was changed and when (see <a href="./../reference/audit-trail">Audit trail</a>). For more recipes, see <a href="./../running-the-event/resolving-issues#competitor-results">Resolving issues on the day</a>.</p><h2 id="prize-giving-and-the-results-board" tabindex="-1">Prize-giving and the results board <a class="header-anchor" href="#prize-giving-and-the-results-board" aria-label="Permalink to &quot;Prize-giving and the results board&quot;">​</a></h2><p>For the presentation, set <strong>Show</strong> to <strong>Top 3</strong> (or however many places you award), choose the classes, then use <strong>Print view</strong> or <strong>Export PDF</strong>. A results list cut to the places being presented makes a straightforward script for whoever reads them out.</p><p>To pin results up at the arena as they come in, use <strong>Print to splits printer…</strong>. It prints a results sheet on a printer, with its own choice of classes, top places and columns, and a preview of the sheet before you print. It opens on the printer this computer&#39;s splits go to, and you can choose any other printer this computer can use (see <a href="./../running-the-event/splits-printing">Printing splits</a>):</p><p><img src="'+c+'" alt="Print results on the splits printer: Show Top 3, classes, organisation and Include options on the left, the printer, and a preview of the roll showing a relay class&#39;s top three teams with their runners"></p><ul><li><strong>Unsettled classes</strong> includes classes where somebody still out could yet take a place; they are marked with an asterisk. Leave it off to print only classes whose places can&#39;t change: those are safe to present.</li><li><strong>On course</strong>, <strong>No status</strong> and <strong>DNS</strong> add those competitors to the sheet as well as the finishers.</li><li><strong>Club</strong> and <strong>Behind</strong> give each its own column. A narrow roll drops them so the names stay readable.</li><li><strong>Team members</strong> lists a relay team&#39;s runners under it, each with their own leg time.</li></ul><h2 id="overall-results-for-a-multi-stage-event" tabindex="-1">Overall results for a multi-stage event <a class="header-anchor" href="#overall-results-for-a-multi-stage-event" aria-label="Permalink to &quot;Overall results for a multi-stage event&quot;">​</a></h2><p>A stage of a <a href="./../event-setup/multi-stage-events">multi-stage event</a> has its own results, read here exactly like any other event&#39;s. The <strong>combined</strong> result across the stages lives on the carnival&#39;s <strong>Standings</strong> tab, not here: open the group header on the Events page.</p><p>The standings show, per class, each competitor&#39;s position, their contribution from each stage, and their total. They update live as a stage runs, so the overall is correct within about half a second of a card being downloaded. A stage that didn&#39;t count is struck through with the reason, and a total that is still provisional carries <code>*</code>.</p><p>See <a href="./../event-setup/multi-stage-events#standings">Standings</a> for what the columns and statuses mean, and <a href="./../event-setup/multi-stage-events#exporting-a-carnival">Exporting a carnival</a> for the overall results as a file.</p><h2 id="the-overall-result-of-a-knock-out-competition" tabindex="-1">The overall result of a knock-out competition <a class="header-anchor" href="#the-overall-result-of-a-knock-out-competition" aria-label="Permalink to &quot;The overall result of a knock-out competition&quot;">​</a></h2><p>A <a href="./../event-setup/knock-out-competitions">knock-out competition</a> is decided by how far each competitor got, not by a total, so its overall result is a <strong>classification</strong> rather than standings. It lives on the competition&#39;s <strong>Classification</strong> tab.</p><p>It updates by itself as cards are downloaded, so it can stay up on a second screen through the final. <strong>Export CSV</strong> at the top of the tab downloads it: each competitor&#39;s overall place, and the place they took in each round. Each round&#39;s own results read and export here exactly like any other event&#39;s. See <a href="./../event-setup/knock-out-competitions#downloading-it">Knock-out competitions</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./exports">Exporting data</a> — the IOF XML and JSON files, one country&#39;s results, combined classes</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — what each status means, and what a results file contains</li><li><a href="./../running-the-event/who-is-still-on-course">Who is still on course</a></li><li><a href="./../running-the-event/resolving-issues">Resolving issues on the day</a></li><li><a href="./../event-setup/results-quarantine">Results quarantine</a></li><li><a href="./../running-the-event/publishing-live-results">Publishing live results online</a> — liveresultat and the meshO cloud</li><li><a href="./end-of-event-checklist">End-of-event checklist</a></li><li><a href="./../screens/leaderboard">Leaderboard</a> — the live results board inside Manager</li></ul>',83)])])}const x=s(g,[["render",p]]);export{T as __pageData,x as default};
